import{_ as l,a0 as o,w as p,s as r,I as a,x as t,a1 as e,A as n,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"如何在 Sway 中設置多個顯示器 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Sway 中設置多個顯示器 | LCTT (202001) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Sway 中設置多個顯示器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Sway 中設置多個顯示器 | LCTT (202001) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202001/20200108 How to setup multiple monitors in sway","title":"如何在 Sway 中設置多個顯示器","tag":"202001","desc":""},"relativePath":"202001/20200108 How to setup multiple monitors in sway.md","filePath":"[post].md"}'),u={name:"202001/20200108 How to setup multiple monitors in sway.md"};function g(h,s,k,m,f,b){const i=o("Link");return p(),r("div",null,[s[23]||(s[23]=a("h1",{id:"如何在-sway-中設置多個顯示器",tabindex:"-1"},[t("如何在 Sway 中設置多個顯示器 "),a("a",{class:"header-anchor",href:"#如何在-sway-中設置多個顯示器","aria-label":"Permalink to “如何在 Sway 中設置多個顯示器”"},"​")],-1)),s[24]||(s[24]=a("p",null,[a("img",{src:"https://fedoramagazine.org/wp-content/uploads/2020/01/sway-multiple-monitors-816x345.png",alt:""})],-1)),a("p",null,[s[1]||(s[1]=t("Sway 是一種平鋪式 Wayland 合成器，具有與 ",-1)),e(i,{href:"https://fedoramagazine.org/getting-started-i3-window-manager/"},{default:n(()=>[...s[0]||(s[0]=[t("i3 X11 窗口管理器",-1)])]),_:1}),s[2]||(s[2]=t("相同的功能、外觀和工作流程。由於 Sway 使用 Wayland 而不是 X11，因此就不能一如既往地使用設置 X11 的工具。這包括 ",-1)),s[3]||(s[3]=a("code",null,"xrandr",-1)),s[4]||(s[4]=t(" 之類的工具，這些工具在 X11 窗口管理器或桌面中用於設置顯示器。這就是為什麼必須通過編輯 Sway 配置文件來設置顯示器的原因，這就是本文的目的。",-1))]),s[25]||(s[25]=d(`<h3 id="獲取你的顯示器-id" tabindex="-1">獲取你的顯示器 ID <a class="header-anchor" href="#獲取你的顯示器-id" aria-label="Permalink to “獲取你的顯示器 ID”">​</a></h3><p>首先，你必須獲得 Sway 用來指代顯示器的名稱。你可以通過運行以下命令進行操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ swaymsg -t get_outputs</span></span></code></pre></div><p>你將獲得所有顯示器的相關信息，每個顯示器都用空行分隔。</p><p>你必須查看每個部分的第一行，以及 <code>Output</code> 之後的內容。例如，當你看到 <code>Output DVI-D-1 &#39;Philips Consumer Electronics Company&#39;</code> 之類的行時，則該輸出 ID 為 <code>DVI-D-1</code>。注意這些 ID 及其所屬的物理監視器。</p><h3 id="編輯配置文件" tabindex="-1">編輯配置文件 <a class="header-anchor" href="#編輯配置文件" aria-label="Permalink to “編輯配置文件”">​</a></h3><p>如果你之前沒有編輯過 Sway 配置文件，則必須通過運行以下命令將其複製到主目錄中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cp -r /etc/sway/config ~/.config/sway/config</span></span></code></pre></div><p>現在，默認配置文件位於 <code>~/.config/sway</code> 中，名為 <code>config</code>。你可以使用任何文本編輯器進行編輯。</p><p>現在你需要做一點數學。想像有一個網格，其原點在左上角。X 和 Y 座標的單位是像素。Y 軸反轉。這意味着，例如，如果你從原點開始，向右移動 100 像素，向下移動 80 像素，則座標將為 <code>(100, 80)</code>。</p><p>你必須計算最終顯示在此網格上的位置。顯示器的位置由左上方的像素指定。例如，如果我們要使用名稱為“HDMI1”且分辨率為 1920×1080 的顯示器，並在其右側使用名稱為 “eDP1” 且分辨率為 1600×900 的筆記本電腦顯示器，則必須在配置文件中鍵入 ：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>output HDMI1 pos 0 0</span></span>
<span class="line"><span>output eDP1 pos 1920 0</span></span></code></pre></div><p>你還可以使用 <code>res</code> 選項手動指定分辨率：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>output HDMI1 pos 0 0 res 1920x1080</span></span>
<span class="line"><span>output eDP1 pos 1920 0 res 1600x900</span></span></code></pre></div><h3 id="將工作空間綁定到顯示器上" tabindex="-1">將工作空間綁定到顯示器上 <a class="header-anchor" href="#將工作空間綁定到顯示器上" aria-label="Permalink to “將工作空間綁定到顯示器上”">​</a></h3><p>與多個監視器一起使用 Sway 在工作區管理中可能會有些棘手。幸運的是，你可以將工作區綁定到特定的顯示器上，因此你可以輕鬆地切換到該顯示器並更有效地使用它。只需通過配置文件中的 <code>workspace</code> 命令即可完成。例如，如果要綁定工作區 1 和 2 到顯示器 “DVI-D-1”，綁定工作區 8 和 9 到顯示器 “HDMI-A-1”，則可以使用以下方法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>workspace 1 output DVI-D-1</span></span>
<span class="line"><span>workspace 2 output DVI-D-1</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>workspace 8 output HDMI-A-1</span></span>
<span class="line"><span>workspace 9 output HDMI-A-1</span></span></code></pre></div>`,18)),a("p",null,[s[6]||(s[6]=t("就是這樣。這就在 Sway 中多顯示器設置的基礎知識。可以在 ",-1)),e(i,{href:"https://github.com/swaywm/sway/wiki#Wiki#Multihead"},{default:n(()=>[...s[5]||(s[5]=[t("https://github.com/swaywm/sway/wiki#Wiki#Multihead",-1)])]),_:1}),s[7]||(s[7]=t(" 中找到更詳細的指南。",-1))]),s[26]||(s[26]=a("hr",null,null,-1)),a("p",null,[s[9]||(s[9]=t("via: ",-1)),e(i,{href:"https://fedoramagazine.org/how-to-setup-multiple-monitors-in-sway/"},{default:n(()=>[...s[8]||(s[8]=[t("https://fedoramagazine.org/how-to-setup-multiple-monitors-in-sway/",-1)])]),_:1})]),a("p",null,[s[14]||(s[14]=t("作者：",-1)),e(i,{href:"https://fedoramagazine.org/author/arte219/"},{default:n(()=>[...s[10]||(s[10]=[t("arte219",-1)])]),_:1}),s[15]||(s[15]=t(" 選題：",-1)),e(i,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[11]||(s[11]=[t("lujun9972",-1)])]),_:1}),s[16]||(s[16]=t(" 譯者：",-1)),e(i,{href:"https://github.com/wxy"},{default:n(()=>[...s[12]||(s[12]=[t("wxy",-1)])]),_:1}),s[17]||(s[17]=t(" 校對：",-1)),e(i,{href:"https://github.com/wxy"},{default:n(()=>[...s[13]||(s[13]=[t("wxy",-1)])]),_:1})]),a("p",null,[s[20]||(s[20]=t("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[18]||(s[18]=[t("LCTT",-1)])]),_:1}),s[21]||(s[21]=t(" 原創編譯，",-1)),e(i,{href:"https://linux.cn/"},{default:n(()=>[...s[19]||(s[19]=[t("Linux中國",-1)])]),_:1}),s[22]||(s[22]=t(" 榮譽推出",-1))])])}const x=l(u,[["render",g]]);export{C as __pageData,x as default};
